insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Oxidation state: Determination', 'While introductory levels of chemistry teaching use postulated oxidation states, the IUPAC recommendation and the Gold Book entry list two entirely general algorithms for the calculation of the oxidation states of elements in chemical compounds.', 'Wikipedia: Oxidation state', 'https://en.wikipedia.org/w/index.php?title=Oxidation_state&oldid=1379006776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'While introductory levels of chemistry teaching use postulated oxidation states, the IUPAC recommendation and the Gold Book entry list two entirely general algorithms for the calculation of the oxidation states of elements in chemical compounds.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Oxidation state: Simple approach without bonding considerations', 'Introductory chemistry uses postulates: the oxidation state for an element in a chemical formula is calculated from the overall charge and postulated oxidation states for all the other atoms. where OS stands for oxidation state. This approach yields correct oxidation states in oxides and hydroxides of any single element, and in acids such as sulfuric acid (H2SO4) or dichromic acid (H2Cr2O7). Its coverage can be extended either by a list of exceptions or by assigning priority to the postulates. The latter works for hydrogen peroxide (H2O2) where the priority of rule 1 leaves both oxygens with oxidation state −1. Additional postulates and their ranking may expand the range of compounds to fit a textbook''s scope. As an example, one postulatory algorithm from many possible; in a sequence of decreasing priority: In a compound or ion, the sum of the oxidation states equals the total charge of the compound or ion. Fluorine in compounds has OS = −1; this extends to chlorine and bromine only when not bonded to a lighter halogen, oxygen or nitrogen. Group 1 and group 2 metals in compounds have OS = +1 and +2, respectively. Hydrogen has OS = +1 but adopts −1 when bonded as a hydride to metals or metalloids.', 'Wikipedia: Oxidation state', 'https://en.wikipedia.org/w/index.php?title=Oxidation_state&oldid=1379006776', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'Introductory chemistry uses postulates: the oxidation state for an element in a chemical formula is calculated from the overall charge and postulated oxidation states for all the other atoms. where OS stands for oxidation state. This approach yields correct oxidation states in oxides and hydroxides of any single element, and in acids such as sulfuric acid (H2SO4) or dichromic acid (H2Cr2O7). Its coverage can be extended either by a list of exceptions or by assigning priority to the postulates. The latter works for hydrogen peroxide (H2O2) where the priority of rule 1 leaves both oxygens with oxidation state −1. Additional postulates and their ranking may expand the range of compounds to fit a textbook''s scope. As an example, one postulatory algorithm from many possible; in a sequence of decreasing priority: In a compound or ion, the sum of the oxidation states equals the total charge of the compound or ion. Fluorine in compounds has OS = −1; this extends to chlorine and bromine only when not bonded to a lighter halogen, oxygen or nitrogen. Group 1 and group 2 metals in compounds have OS = +1 and +2, respectively. Hydrogen has OS = +1 but adopts −1 when bonded as a hydride to metals or metalloids.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell', 'A galvanic cell or voltaic cell, named after the scientists Luigi Galvani and Alessandro Volta, respectively, is an electrochemical cell in which an electric current is generated from spontaneous oxidation–reduction reactions. An example of a galvanic cell consists of two different metals, each immersed in separate beakers containing their respective metal ions in solution that are connected by a salt bridge or separated by a porous membrane. Volta is the inventor of the voltaic pile, the first electrical battery. Common usage of the word battery has evolved to include a single galvanic cell, but the first batteries had many galvanic cells.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'A galvanic cell or voltaic cell, named after the scientists Luigi Galvani and Alessandro Volta, respectively, is an electrochemical cell in which an electric current is generated from spontaneous oxidation–reduction reactions. An example of a galvanic cell consists of two different metals, each immersed in separate beakers containing their respective metal ions in solution that are connected by a salt bridge or separated by a porous membrane. Volta is the inventor of the voltaic pile, the first electrical battery. Common usage of the word battery has evolved to include a single galvanic cell, but the first batteries had many galvanic cells.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Principles', 'Galvanic cells are extensions of spontaneous redox reactions, but have been designed to harness the energy produced from said reaction. For example, when one immerses a strip of zinc metal (Zn) in an aqueous solution of copper sulfate (CuSO4), dark-colored solid deposits will collect on the surface of the zinc metal and the blue color characteristic of the Cu2+ ion disappears from the solution. The depositions on the surface of the zinc metal consist of copper metal, and the solution now contains zinc ions. This reaction is represented by:', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'Galvanic cells are extensions of spontaneous redox reactions, but have been designed to harness the energy produced from said reaction. For example, when one immerses a strip of zinc metal (Zn) in an aqueous solution of copper sulfate (CuSO4), dark-colored solid deposits will collect on the surface of the zinc metal and the blue color characteristic of the Cu2+ ion disappears from the solution. The depositions on the surface of the zinc metal consist of copper metal, and the solution now contains zinc ions. This reaction is represented by:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Principles', 'In this redox reaction, Zn is oxidized to Zn2+ and Cu2+ is reduced to Cu. When electrons are transferred directly from Zn to Cu2+, the enthalpy of reaction is lost to the surroundings as heat. However, the same reaction can be carried out in a galvanic cell, allowing some of the chemical energy released to be converted into electrical energy. In its simplest form, a half-cell consists of a solid metal (called an electrode) that is submerged in a solution; the solution contains cations (+) of the electrode metal and anions (−) to balance the charge of the cations. The full cell consists of two half-cells, usually connected by a semi-permeable membrane or by a salt bridge that prevents the ions of the more noble metal from plating out at the other electrode. A specific example is the Daniell cell (see figure), with a zinc (Zn) half-cell containing a solution of ZnSO4 (zinc sulfate) and a copper (Cu) half-cell containing a solution of CuSO4 (copper sulfate). A salt bridge is used here to complete the electric circuit.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In this redox reaction, Zn is oxidized to Zn2+ and Cu2+ is reduced to Cu. When electrons are transferred directly from Zn to Cu2+, the enthalpy of reaction is lost to the surroundings as heat. However, the same reaction can be carried out in a galvanic cell, allowing some of the chemical energy released to be converted into electrical energy. In its simplest form, a half-cell consists of a solid metal (called an electrode) that is submerged in a solution; the solution contains cations (+) of the electrode metal and anions (−) to balance the charge of the cations. The full cell consists of two half-cells, usually connected by a semi-permeable membrane or by a salt bridge that prevents the ions of the more noble metal from plating out at the other electrode. A specific example is the Daniell cell (see figure), with a zinc (Zn) half-cell containing a solution of ZnSO4 (zinc sulfate) and a copper (Cu) half-cell containing a solution of CuSO4 (copper sulfate). A salt bridge is used here to complete the electric circuit.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Principles', 'If an external electrical conductor connects the copper and zinc electrodes, zinc from the zinc electrode dissolves into the solution as Zn2+ ions (oxidation), releasing electrons that enter the external conductor. To compensate for the increased zinc ion concentration, via the salt bridge zinc ions (cations) leave and sulfate ions (anions) enter the zinc half-cell. In the copper half-cell, the copper ions plate onto the copper electrode (reduction), taking up electrons that leave the external conductor. Since the Cu2+ ions (cations) plate onto the copper electrode, the latter is called the cathode. Correspondingly the zinc electrode is the anode. The electrochemical reaction is: This is the same reaction as given in the previous example. In addition, electrons flow through the external conductor, which is the primary application of the galvanic cell. As discussed under cell voltage, the electromotive force of the cell is the difference of the half-cell potentials, a measure of the relative ease of dissolution of the two electrodes into the electrolyte. The emf depends on both the electrodes and on the electrolyte, an indication that the emf is chemical in nature.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'If an external electrical conductor connects the copper and zinc electrodes, zinc from the zinc electrode dissolves into the solution as Zn2+ ions (oxidation), releasing electrons that enter the external conductor. To compensate for the increased zinc ion concentration, via the salt bridge zinc ions (cations) leave and sulfate ions (anions) enter the zinc half-cell. In the copper half-cell, the copper ions plate onto the copper electrode (reduction), taking up electrons that leave the external conductor. Since the Cu2+ ions (cations) plate onto the copper electrode, the latter is called the cathode. Correspondingly the zinc electrode is the anode. The electrochemical reaction is: This is the same reaction as given in the previous example. In addition, electrons flow through the external conductor, which is the primary application of the galvanic cell. As discussed under cell voltage, the electromotive force of the cell is the difference of the half-cell potentials, a measure of the relative ease of dissolution of the two electrodes into the electrolyte. The emf depends on both the electrodes and on the electrolyte, an indication that the emf is chemical in nature.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Half reactions and conventions', 'A half-cell contains a metal in two oxidation states. Inside an isolated half-cell, there is an oxidation-reduction (redox) reaction that is in chemical equilibrium, a condition written symbolically as follows (here, "M" represents a metal cation, an atom that has a charge imbalance due to the loss of n electrons): A galvanic cell consists of two half-cells, such that the electrode of one half-cell is composed of metal A, and the electrode of the other half-cell is composed of metal B; the redox reactions for the two separate half-cells are thus: m A + n B m+ ⇌ n B + m A n+ In other words, the metal atoms of one half-cell are oxidized while the metal cations of the other half-cell are reduced. By separating the metals in two half-cells, their reaction can be controlled in a way that forces transfer of electrons through the external circuit where they can do useful work. The electrodes are connected with a metal wire in order to conduct the electrons that participate in the reaction.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'A half-cell contains a metal in two oxidation states. Inside an isolated half-cell, there is an oxidation-reduction (redox) reaction that is in chemical equilibrium, a condition written symbolically as follows (here, "M" represents a metal cation, an atom that has a charge imbalance due to the loss of n electrons): A galvanic cell consists of two half-cells, such that the electrode of one half-cell is composed of metal A, and the electrode of the other half-cell is composed of metal B; the redox reactions for the two separate half-cells are thus: m A + n B m+ ⇌ n B + m A n+ In other words, the metal atoms of one half-cell are oxidized while the metal cations of the other half-cell are reduced. By separating the metals in two half-cells, their reaction can be controlled in a way that forces transfer of electrons through the external circuit where they can do useful work. The electrodes are connected with a metal wire in order to conduct the electrons that participate in the reaction.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Half reactions and conventions', 'In one half-cell, dissolved metal B cations combine with the free electrons that are available at the interface between the solution and the metal B electrode; these cations are thereby neutralized, causing them to precipitate from solution as deposits on the metal B electrode, a process known as plating. This reduction reaction causes the free electrons throughout the metal B electrode, the wire, and the metal A electrode to be pulled into the metal B electrode. Consequently, electrons are wrestled away from some of the atoms of the metal A electrode, as though the metal B cations were reacting directly with them; those metal A atoms become cations that dissolve into the surrounding solution. As this reaction continues, the half-cell with the metal A electrode develops a positively charged solution (because the metal A cations dissolve into it), while the other half-cell develops a negatively charged solution (because the metal B cations precipitate out of it, leaving behind the anions); unabated, this imbalance in charge would stop the reaction. The solutions of the half-cells are connected by a salt bridge or a porous plate that allows ions to pass from one solution to the other, which balances the charges of the solutions and allows the reaction to continue.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In one half-cell, dissolved metal B cations combine with the free electrons that are available at the interface between the solution and the metal B electrode; these cations are thereby neutralized, causing them to precipitate from solution as deposits on the metal B electrode, a process known as plating. This reduction reaction causes the free electrons throughout the metal B electrode, the wire, and the metal A electrode to be pulled into the metal B electrode. Consequently, electrons are wrestled away from some of the atoms of the metal A electrode, as though the metal B cations were reacting directly with them; those metal A atoms become cations that dissolve into the surrounding solution. As this reaction continues, the half-cell with the metal A electrode develops a positively charged solution (because the metal A cations dissolve into it), while the other half-cell develops a negatively charged solution (because the metal B cations precipitate out of it, leaving behind the anions); unabated, this imbalance in charge would stop the reaction. The solutions of the half-cells are connected by a salt bridge or a porous plate that allows ions to pass from one solution to the other, which balances the charges of the solutions and allows the reaction to continue.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Half reactions and conventions', 'The anode is the electrode where oxidation (loss of electrons) takes place (metal A electrode); in a galvanic cell, it is the negative electrode, because when oxidation occurs, electrons are left behind on the electrode. These electrons then flow through the external circuit to the cathode (positive electrode) (while in electrolysis, an electric current drives electron flow in the opposite direction and the anode is the positive electrode). The cathode is the electrode where reduction (gain of electrons) takes place (metal B electrode); in a galvanic cell, it is the positive electrode, as ions get reduced by taking up electrons from the electrode and plate out (while in electrolysis, the cathode is the negative terminal and attracts positive ions from the solution). In both cases, the statement ''the cathode attracts cations'' is true. The Weston cell has an anode composed of cadmium mercury amalgam, and a cathode composed of pure mercury. The electrolyte is a (saturated) solution of cadmium sulfate. The depolarizer is a paste of mercurous sulfate. When the electrolyte solution is saturated, the voltage of the cell is very reproducible; hence, in 1911, it was adopted as an international standard for voltage.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'The anode is the electrode where oxidation (loss of electrons) takes place (metal A electrode); in a galvanic cell, it is the negative electrode, because when oxidation occurs, electrons are left behind on the electrode. These electrons then flow through the external circuit to the cathode (positive electrode) (while in electrolysis, an electric current drives electron flow in the opposite direction and the anode is the positive electrode). The cathode is the electrode where reduction (gain of electrons) takes place (metal B electrode); in a galvanic cell, it is the positive electrode, as ions get reduced by taking up electrons from the electrode and plate out (while in electrolysis, the cathode is the negative terminal and attracts positive ions from the solution). In both cases, the statement ''the cathode attracts cations'' is true. The Weston cell has an anode composed of cadmium mercury amalgam, and a cathode composed of pure mercury. The electrolyte is a (saturated) solution of cadmium sulfate. The depolarizer is a paste of mercurous sulfate. When the electrolyte solution is saturated, the voltage of the cell is very reproducible; hence, in 1911, it was adopted as an international standard for voltage.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Galvanic cell: Half reactions and conventions', 'In the strictest sense, a battery is a set of two or more galvanic cells that are connected in series to form a single source of voltage. For instance, a typical 12 V lead–acid battery has six galvanic cells connected in series, with the anodes composed of lead and cathodes composed of lead dioxide, both immersed in sulfuric acid. Large central office battery rooms – in a telephone exchange to provide power for subscribers'' land-line telephones, for instance – may have many cells, connected both in series and parallel: Individual cells are connected in series as a battery of cells with some standard voltage (c. 40 V), and banks of such serial batteries, themselves connected in parallel, to provide adequate amperage to supply a typical peak demand for telephone connections.', 'Wikipedia: Galvanic cell', 'https://en.wikipedia.org/w/index.php?title=Galvanic_cell&oldid=1377191244', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In the strictest sense, a battery is a set of two or more galvanic cells that are connected in series to form a single source of voltage. For instance, a typical 12 V lead–acid battery has six galvanic cells connected in series, with the anodes composed of lead and cathodes composed of lead dioxide, both immersed in sulfuric acid. Large central office battery rooms – in a telephone exchange to provide power for subscribers'' land-line telephones, for instance – may have many cells, connected both in series and parallel: Individual cells are connected in series as a battery of cells with some standard voltage (c. 40 V), and banks of such serial batteries, themselves connected in parallel, to provide adequate amperage to supply a typical peak demand for telephone connections.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Electrolytic cell', 'An electrolytic cell is an electrochemical cell that uses an external source of electrical energy to drive a non-spontaneous chemical reaction, a process known as electrolysis. In the cell, a voltage is applied between the two electrodes—an anode (positively charged) and a cathode (negatively charged)—immersed in an electrolyte solution. This contrasts with a galvanic cell, which produces electrical energy from a spontaneous chemical reaction and forms the basis of batteries. The net reaction in an electrolytic cell is a non-spontaneous (Gibbs free energy is positive), whereas in a galvanic cell, it is spontaneous (Gibbs free energy is negative).', 'Wikipedia: Electrolytic cell', 'https://en.wikipedia.org/w/index.php?title=Electrolytic_cell&oldid=1301506653', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'An electrolytic cell is an electrochemical cell that uses an external source of electrical energy to drive a non-spontaneous chemical reaction, a process known as electrolysis. In the cell, a voltage is applied between the two electrodes—an anode (positively charged) and a cathode (negatively charged)—immersed in an electrolyte solution. This contrasts with a galvanic cell, which produces electrical energy from a spontaneous chemical reaction and forms the basis of batteries. The net reaction in an electrolytic cell is a non-spontaneous (Gibbs free energy is positive), whereas in a galvanic cell, it is spontaneous (Gibbs free energy is negative).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Electrolytic cell: Principles', 'In an electrolytic cell, a current passes through the cell by an external voltage, causing a non-spontaneous chemical reaction to proceed. In a galvanic cell, the progress of a spontaneous chemical reaction causes an electric current to flow. An equilibrium electrochemical cell exists in the state between an electrolytic cell and a galvanic cell. The tendency of a spontaneous reaction to push a current through the external circuit is exactly balanced by a voltage so that no current flows. If this voltage is increased, the cell becomes an electrolytic cell, and if it is decreased, the cell becomes a galvanic cell. An electrolytic cell has three components: an electrolyte and two electrodes (a cathode and an anode). The electrolyte is usually a solution of water or other solvents in which ions are dissolved. Molten salts such as sodium chloride can also function as electrolytes. When driven by an external voltage applied to the electrodes, the ions in the electrolyte are attracted to an electrode with the opposite charge, where charge-transferring (also called faradaic or redox) reactions can take place. Only with an external voltage of correct polarity and sufficient magnitude can an electrolytic cell decompose a normally stable, or inert chemical compound in the solution. The electrical energy provided can produce a chemical reaction that would otherwise not occur spontaneously.', 'Wikipedia: Electrolytic cell', 'https://en.wikipedia.org/w/index.php?title=Electrolytic_cell&oldid=1301506653', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In an electrolytic cell, a current passes through the cell by an external voltage, causing a non-spontaneous chemical reaction to proceed. In a galvanic cell, the progress of a spontaneous chemical reaction causes an electric current to flow. An equilibrium electrochemical cell exists in the state between an electrolytic cell and a galvanic cell. The tendency of a spontaneous reaction to push a current through the external circuit is exactly balanced by a voltage so that no current flows. If this voltage is increased, the cell becomes an electrolytic cell, and if it is decreased, the cell becomes a galvanic cell. An electrolytic cell has three components: an electrolyte and two electrodes (a cathode and an anode). The electrolyte is usually a solution of water or other solvents in which ions are dissolved. Molten salts such as sodium chloride can also function as electrolytes. When driven by an external voltage applied to the electrodes, the ions in the electrolyte are attracted to an electrode with the opposite charge, where charge-transferring (also called faradaic or redox) reactions can take place. Only with an external voltage of correct polarity and sufficient magnitude can an electrolytic cell decompose a normally stable, or inert chemical compound in the solution. The electrical energy provided can produce a chemical reaction that would otherwise not occur spontaneously.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Electrolytic cell: Principles', 'Michael Faraday defined the cathode of a cell as the electrode to which cations (positively charged ions, such as silver ions Ag+) flow within the cell, to be reduced by reacting with electrons (negatively charged) from that electrode. Likewise, he defined the anode as the electrode to which anions (negatively charged ions, like chloride ions Cl−) flow within the cell, to be oxidized by depositing electrons on the electrode. To an external wire connected to the electrodes of a galvanic cell (or battery), forming an electric circuit, the cathode is positive and the anode is negative. Thus positive electric current flows from the cathode to the anode through the external circuit in the case of a galvanic cell.', 'Wikipedia: Electrolytic cell', 'https://en.wikipedia.org/w/index.php?title=Electrolytic_cell&oldid=1301506653', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'Michael Faraday defined the cathode of a cell as the electrode to which cations (positively charged ions, such as silver ions Ag+) flow within the cell, to be reduced by reacting with electrons (negatively charged) from that electrode. Likewise, he defined the anode as the electrode to which anions (negatively charged ions, like chloride ions Cl−) flow within the cell, to be oxidized by depositing electrons on the electrode. To an external wire connected to the electrodes of a galvanic cell (or battery), forming an electric circuit, the cathode is positive and the anode is negative. Thus positive electric current flows from the cathode to the anode through the external circuit in the case of a galvanic cell.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Electrolytic cell: Applications', 'Electrolytic cells are often used to decompose chemical compounds, in a process called electrolysis—with electro meaning electricity and the Greek word lysis means to break up. Important examples of electrolysis are the decomposition of water into hydrogen and oxygen, and bauxite into aluminum and other chemicals. Electroplating (e.g., of copper, silver, nickel, or chromium) is done using an electrolytic cell. Electrolysis is a technique that uses a direct electric current (DC). Commercially, electrolytic cells are used in the electrorefining and electrowinning of several non-ferrous metals. Most high-purity aluminum, copper, zinc, and lead are produced industrially in electrolytic cells. As already noted, water, particularly when ions are added (saltwater or acidic water), can be electrolyzed (subjected to electrolysis). When driven by an external source of voltage, hydrogen (H+) ions flow to the cathode to combine with electrons to produce hydrogen gas in a reduction reaction. Likewise, hydroxide (OH−) ions flow to the anode to release electrons and a hydrogen (H+) ion to produce oxygen gas in an oxidation reaction. In molten sodium chloride (NaCl), when a current is passed through the salt the anode oxidizes chloride ions (Cl−) to chlorine gas, it releases electrons to the anode. Likewise, the cathode reduces sodium ions (Na+), which accepts electrons from the cathode and deposits them on the cathode as sodium metal.', 'Wikipedia: Electrolytic cell', 'https://en.wikipedia.org/w/index.php?title=Electrolytic_cell&oldid=1301506653', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'Electrolytic cells are often used to decompose chemical compounds, in a process called electrolysis—with electro meaning electricity and the Greek word lysis means to break up. Important examples of electrolysis are the decomposition of water into hydrogen and oxygen, and bauxite into aluminum and other chemicals. Electroplating (e.g., of copper, silver, nickel, or chromium) is done using an electrolytic cell. Electrolysis is a technique that uses a direct electric current (DC). Commercially, electrolytic cells are used in the electrorefining and electrowinning of several non-ferrous metals. Most high-purity aluminum, copper, zinc, and lead are produced industrially in electrolytic cells. As already noted, water, particularly when ions are added (saltwater or acidic water), can be electrolyzed (subjected to electrolysis). When driven by an external source of voltage, hydrogen (H+) ions flow to the cathode to combine with electrons to produce hydrogen gas in a reduction reaction. Likewise, hydroxide (OH−) ions flow to the anode to release electrons and a hydrogen (H+) ion to produce oxygen gas in an oxidation reaction. In molten sodium chloride (NaCl), when a current is passed through the salt the anode oxidizes chloride ions (Cl−) to chlorine gas, it releases electrons to the anode. Likewise, the cathode reduces sodium ions (Na+), which accepts electrons from the cathode and deposits them on the cathode as sodium metal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Electrolytic cell: Applications', 'Sodium chloride that has been dissolved in water can also be electrolyzed. The anode oxidizes the chloride ions (Cl−), and produces chlorine (Cl2) gas, and, depending on the pH of the solution, can produce Hypochlorous acid. However, at the cathode, instead of sodium ions being reduced to sodium metal, water molecules are reduced to hydroxide ions (OH−) and hydrogen gas (H2). The overall result of the electrolysis is the production of chlorine gas at the anode, aqueous hypochlorous acid as the anolyte, hydrogen gas at the cathode, and aqueous sodium hydroxide (NaOH) as the catholyte. Industrially, this is known as the chloralkali process.', 'Wikipedia: Electrolytic cell', 'https://en.wikipedia.org/w/index.php?title=Electrolytic_cell&oldid=1301506653', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'Sodium chloride that has been dissolved in water can also be electrolyzed. The anode oxidizes the chloride ions (Cl−), and produces chlorine (Cl2) gas, and, depending on the pH of the solution, can produce Hypochlorous acid. However, at the cathode, instead of sodium ions being reduced to sodium metal, water molecules are reduced to hydroxide ions (OH−) and hydrogen gas (H2). The overall result of the electrolysis is the production of chlorine gas at the anode, aqueous hypochlorous acid as the anolyte, hydrogen gas at the cathode, and aqueous sodium hydroxide (NaOH) as the catholyte. Industrially, this is known as the chloralkali process.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Standard electrode potential', 'In electrochemistry, standard electrode potential E⦵ or E⦵red, is the electrode potential (a measure of the reducing power of any element or compound) which the IUPAC "Gold Book" defines as "the value of the standard emf (electromotive force) of a cell in which molecular hydrogen under standard pressure is oxidized to solvated protons at the left-hand electrode".', 'Wikipedia: Standard electrode potential', 'https://en.wikipedia.org/w/index.php?title=Standard_electrode_potential&oldid=1377006226', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In electrochemistry, standard electrode potential E⦵ or E⦵red, is the electrode potential (a measure of the reducing power of any element or compound) which the IUPAC "Gold Book" defines as "the value of the standard emf (electromotive force) of a cell in which molecular hydrogen under standard pressure is oxidized to solvated protons at the left-hand electrode".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Standard electrode potential: Background', 'The basis for an electrochemical cell, such as the galvanic cell, is always a redox reaction which can be broken down into two half-reactions: oxidation at anode (loss of electron) and reduction at cathode (gain of electron). Electricity is produced due to the difference of electric potential between the individual potentials of the two metal electrodes with respect to the electrolyte. Although the overall potential of a cell can be measured, there is no simple way to accurately measure the electrode/electrolyte potentials in isolation. The electric potential also varies with temperature, concentration and pressure. Since the oxidation potential of a half-reaction is the negative of the reduction potential in a redox reaction, it is sufficient to calculate either one of the potentials. Therefore, standard electrode potential is commonly written as standard reduction potential.', 'Wikipedia: Standard electrode potential', 'https://en.wikipedia.org/w/index.php?title=Standard_electrode_potential&oldid=1377006226', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'The basis for an electrochemical cell, such as the galvanic cell, is always a redox reaction which can be broken down into two half-reactions: oxidation at anode (loss of electron) and reduction at cathode (gain of electron). Electricity is produced due to the difference of electric potential between the individual potentials of the two metal electrodes with respect to the electrolyte. Although the overall potential of a cell can be measured, there is no simple way to accurately measure the electrode/electrolyte potentials in isolation. The electric potential also varies with temperature, concentration and pressure. Since the oxidation potential of a half-reaction is the negative of the reduction potential in a redox reaction, it is sufficient to calculate either one of the potentials. Therefore, standard electrode potential is commonly written as standard reduction potential.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Standard electrode potential: Calculation', 'The galvanic cell potential results from the voltage difference of a pair of electrodes. It is not possible to measure an absolute value for each electrode separately. However, the potential of a reference electrode, standard hydrogen electrode (SHE), is defined as to 0.00 V. An electrode with unknown electrode potential can be paired with either the standard hydrogen electrode, or another electrode whose potential has already been measured, to determine its "absolute" potential. Since the electrode potentials are conventionally defined as reduction potentials, the sign of the potential for the metal electrode being oxidized must be reversed when calculating the overall cell potential. The electrode potentials are independent of the number of electrons transferred —they are expressed in volts, which measure energy per electron transferred—and so the two electrode potentials can be simply combined to give the overall cell potential even if different numbers of electrons are involved in the two electrode reactions. For practical measurements, the electrode in question is connected to the positive terminal of the electrometer, while the standard hydrogen electrode is connected to the negative terminal.', 'Wikipedia: Standard electrode potential', 'https://en.wikipedia.org/w/index.php?title=Standard_electrode_potential&oldid=1377006226', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'The galvanic cell potential results from the voltage difference of a pair of electrodes. It is not possible to measure an absolute value for each electrode separately. However, the potential of a reference electrode, standard hydrogen electrode (SHE), is defined as to 0.00 V. An electrode with unknown electrode potential can be paired with either the standard hydrogen electrode, or another electrode whose potential has already been measured, to determine its "absolute" potential. Since the electrode potentials are conventionally defined as reduction potentials, the sign of the potential for the metal electrode being oxidized must be reversed when calculating the overall cell potential. The electrode potentials are independent of the number of electrons transferred —they are expressed in volts, which measure energy per electron transferred—and so the two electrode potentials can be simply combined to give the overall cell potential even if different numbers of electrons are involved in the two electrode reactions. For practical measurements, the electrode in question is connected to the positive terminal of the electrometer, while the standard hydrogen electrode is connected to the negative terminal.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Standard electrode potential: Reversible electrode', 'A reversible electrode is an electrode that owes its potential to changes of a reversible nature. A first condition to be fulfilled is that the system is close to the chemical equilibrium. A second set of conditions is that the system is submitted to very small solicitations spread on a sufficient period of time so, that the chemical equilibrium conditions nearly always prevail. In theory, it is very difficult to experimentally achieve reversible conditions because any perturbation imposed to a system near equilibrium in a finite time forces it out of equilibrium. However, if the solicitations exerted on the system are sufficiently small and applied slowly, one can consider an electrode to be reversible. By nature, electrode reversibility depends on the experimental conditions and the way the electrode is operated. For example, electrodes used in electroplating are operated with a high over-potential to force the reduction of a given metal cation to be deposited onto a metallic surface to be protected. Such a system is far from equilibrium and continuously submitted to important and constant changes in a short period of time', 'Wikipedia: Standard electrode potential', 'https://en.wikipedia.org/w/index.php?title=Standard_electrode_potential&oldid=1377006226', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'A reversible electrode is an electrode that owes its potential to changes of a reversible nature. A first condition to be fulfilled is that the system is close to the chemical equilibrium. A second set of conditions is that the system is submitted to very small solicitations spread on a sufficient period of time so, that the chemical equilibrium conditions nearly always prevail. In theory, it is very difficult to experimentally achieve reversible conditions because any perturbation imposed to a system near equilibrium in a finite time forces it out of equilibrium. However, if the solicitations exerted on the system are sufficiently small and applied slowly, one can consider an electrode to be reversible. By nature, electrode reversibility depends on the experimental conditions and the way the electrode is operated. For example, electrodes used in electroplating are operated with a high over-potential to force the reduction of a given metal cation to be deposited onto a metallic surface to be protected. Such a system is far from equilibrium and continuously submitted to important and constant changes in a short period of time');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Standard electrode potential: Standard reduction potential table', 'The larger the value of the standard reduction potential, the easier it is for the element to be reduced (gain electrons); in other words, they are better oxidizing agents. For example, F2(g) has a standard reduction potential of +2.87 V and Li+(aq) has −3.05 V: The highly positive standard reduction potential of F2(g) means it is reduced easily and is therefore a good oxidizing agent. In contrast, the greatly negative standard reduction potential of Li+(aq) indicates that it is not easily reduced. Instead, Li(s) would rather undergo oxidation (hence it is a good reducing agent). A further example: Zn2+(aq) + 2 e− ⇌ Zn(s) has a standard reduction potential of −0.76 V and thus: Zn(s) can be oxidized by any other electrode whose standard reduction potential is greater than −0.76 V e.g., 2 H+(aq) + 2 e− ⇌ H2(g) (0 V), Cu2+(aq) + 2 e− ⇌ Cu(s) (0.34 V), F2(g) + 2 e− ⇌ 2 F−(aq) (2.87 V) Zn2+(aq) can be reduced by any electrode with standard reduction potential less than −0.76 V e.g. H−(aq) (H2(g) + 2 e− ⇌ 2 H−(aq) (−2.23 V)), Na(s) (Na+(aq) + e− ⇌ Na(s) (−2.71 V)), Li(s) (Li+(aq) + e− ⇌ Li(s) (−3.05 V)).', 'Wikipedia: Standard electrode potential', 'https://en.wikipedia.org/w/index.php?title=Standard_electrode_potential&oldid=1377006226', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'The larger the value of the standard reduction potential, the easier it is for the element to be reduced (gain electrons); in other words, they are better oxidizing agents. For example, F2(g) has a standard reduction potential of +2.87 V and Li+(aq) has −3.05 V: The highly positive standard reduction potential of F2(g) means it is reduced easily and is therefore a good oxidizing agent. In contrast, the greatly negative standard reduction potential of Li+(aq) indicates that it is not easily reduced. Instead, Li(s) would rather undergo oxidation (hence it is a good reducing agent). A further example: Zn2+(aq) + 2 e− ⇌ Zn(s) has a standard reduction potential of −0.76 V and thus: Zn(s) can be oxidized by any other electrode whose standard reduction potential is greater than −0.76 V e.g., 2 H+(aq) + 2 e− ⇌ H2(g) (0 V), Cu2+(aq) + 2 e− ⇌ Cu(s) (0.34 V), F2(g) + 2 e− ⇌ 2 F−(aq) (2.87 V) Zn2+(aq) can be reduced by any electrode with standard reduction potential less than −0.76 V e.g. H−(aq) (H2(g) + 2 e− ⇌ 2 H−(aq) (−2.23 V)), Na(s) (Na+(aq) + e− ⇌ Na(s) (−2.71 V)), Li(s) (Li+(aq) + e− ⇌ Li(s) (−3.05 V)).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Standard electrode potential: Standard reduction potential table', 'In a galvanic cell, where a spontaneous redox reaction drives the cell to produce an electric potential, Gibbs free energy ΔG⦵ must be negative, in accordance with the following equation: where n is number of moles of electrons per mole of products and F is the Faraday constant, ~ 96 485 C/mol. If E⦵cell > 0, then the process is spontaneous (galvanic cell): ΔcellG⦵ < 0, and energy is liberated. If E⦵cell < 0, then the process is non-spontaneous (electrolytic cell): ΔcellG⦵ > 0, and energy is consumed. Thus in order to have a spontaneous reaction (ΔcellG⦵ < 0), E⦵cell must be positive, where: where E⦵cathode is the standard potential (E⦵red) at the cathode (called the standard cathodic potential or standard reduction potential) and E⦵anode is the standard potential (E⦵red) at the anode (called the standard anodic potential or standard oxidation potential) as given in the table of standard electrode potential.', 'Wikipedia: Standard electrode potential', 'https://en.wikipedia.org/w/index.php?title=Standard_electrode_potential&oldid=1377006226', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In a galvanic cell, where a spontaneous redox reaction drives the cell to produce an electric potential, Gibbs free energy ΔG⦵ must be negative, in accordance with the following equation: where n is number of moles of electrons per mole of products and F is the Faraday constant, ~ 96 485 C/mol. If E⦵cell > 0, then the process is spontaneous (galvanic cell): ΔcellG⦵ < 0, and energy is liberated. If E⦵cell < 0, then the process is non-spontaneous (electrolytic cell): ΔcellG⦵ > 0, and energy is consumed. Thus in order to have a spontaneous reaction (ΔcellG⦵ < 0), E⦵cell must be positive, where: where E⦵cathode is the standard potential (E⦵red) at the cathode (called the standard cathodic potential or standard reduction potential) and E⦵anode is the standard potential (E⦵red) at the anode (called the standard anodic potential or standard oxidation potential) as given in the table of standard electrode potential.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Nernst equation', 'In electrochemistry, the Nernst equation is a chemical thermodynamical relationship in electrochemistry that permits the calculation of the reduction potential of a reaction (half-cell or full cell reaction) from the standard electrode potential, absolute temperature, the number of electrons transferred in the redox reaction, and activities (often approximated by concentrations) of the chemical species undergoing reduction and oxidation respectively. It was named after Walther Nernst, a German physical chemist who is the author of the equation. It has applications in cell physiology and biophysics, concerning the cell membrane potential.', 'Wikipedia: Nernst equation', 'https://en.wikipedia.org/w/index.php?title=Nernst_equation&oldid=1376884524', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'In electrochemistry, the Nernst equation is a chemical thermodynamical relationship in electrochemistry that permits the calculation of the reduction potential of a reaction (half-cell or full cell reaction) from the standard electrode potential, absolute temperature, the number of electrons transferred in the redox reaction, and activities (often approximated by concentrations) of the chemical species undergoing reduction and oxidation respectively. It was named after Walther Nernst, a German physical chemist who is the author of the equation. It has applications in cell physiology and biophysics, concerning the cell membrane potential.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Nernst equation: General form with chemical activities', 'When an oxidized species (Ox) accepts a number z of electrons ( e−) to be converted in its reduced form (Red), the half-reaction is expressed as: The reaction quotient (Qr), also often called the ion activity product (IAP), is the ratio between the chemical activities (a) of the reduced form (the reductant, aRed) and the oxidized form (the oxidant, aOx). The chemical activity of a dissolved species is a quantity used for taking into account the electrical interactions between all ions present in solution at elevated concentrations. For a given dissolved species, its chemical activity (a) is the product of its activity coefficient (γ) by its molar (mol/L solution), or molal (mol/kg water), concentration (C): a = γ C. So, if the concentration (C, also denoted here below with square brackets [ ]) of all the dissolved species of interest are sufficiently low and that their activity coefficients are close to unity, their chemical activities can be approximated by their concentrations as commonly done when simplifying, or idealizing, a reaction in order to have a simple reference case: At chemical equilibrium, the quotient Qr of the activity of the reaction product (aRed) by the reagent activity (aOx) is equal to the equilibrium constant K of the half-reaction:', 'Wikipedia: Nernst equation', 'https://en.wikipedia.org/w/index.php?title=Nernst_equation&oldid=1376884524', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'When an oxidized species (Ox) accepts a number z of electrons ( e−) to be converted in its reduced form (Red), the half-reaction is expressed as: The reaction quotient (Qr), also often called the ion activity product (IAP), is the ratio between the chemical activities (a) of the reduced form (the reductant, aRed) and the oxidized form (the oxidant, aOx). The chemical activity of a dissolved species is a quantity used for taking into account the electrical interactions between all ions present in solution at elevated concentrations. For a given dissolved species, its chemical activity (a) is the product of its activity coefficient (γ) by its molar (mol/L solution), or molal (mol/kg water), concentration (C): a = γ C. So, if the concentration (C, also denoted here below with square brackets [ ]) of all the dissolved species of interest are sufficiently low and that their activity coefficients are close to unity, their chemical activities can be approximated by their concentrations as commonly done when simplifying, or idealizing, a reaction in order to have a simple reference case: At chemical equilibrium, the quotient Qr of the activity of the reaction product (aRed) by the reagent activity (aOx) is equal to the equilibrium constant K of the half-reaction:');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Nernst equation: General form with chemical activities', 'The standard thermodynamics also says that the actual Gibbs free energy ΔG is related to the free energy change under standard state ΔGo by the relationship: where Qr is the reaction quotient and R is the universal ideal gas constant. The cell potential E associated with the electrochemical reaction is defined as the decrease in Gibbs free energy per coulomb of charge transferred, which leads to the relationship The constant F (the Faraday constant) is a unit conversion factor F = NAq, where NA is the Avogadro constant and q is the fundamental electron charge. This immediately leads to the Nernst equation, which for an electrochemical half-cell is For a complete electrochemical reaction (full cell), the equation can be written as Ecell is the cell potential (electromotive force) at the temperature of interest, R is the universal ideal gas constant: R = 8.31446261815324 J K−1 mol−1, z is the number of electrons transferred in the cell reaction or half-reaction, F is Faraday''s constant, the magnitude of charge (in coulombs) per mole of electrons: F = 96485.3321233100184 C mol−1, a is the chemical activity for the relevant species, where aRed is the activity of the reduced form and aOx is the activity of the oxidized form.', 'Wikipedia: Nernst equation', 'https://en.wikipedia.org/w/index.php?title=Nernst_equation&oldid=1376884524', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'electrochemistry' and body = 'The standard thermodynamics also says that the actual Gibbs free energy ΔG is related to the free energy change under standard state ΔGo by the relationship: where Qr is the reaction quotient and R is the universal ideal gas constant. The cell potential E associated with the electrochemical reaction is defined as the decrease in Gibbs free energy per coulomb of charge transferred, which leads to the relationship The constant F (the Faraday constant) is a unit conversion factor F = NAq, where NA is the Avogadro constant and q is the fundamental electron charge. This immediately leads to the Nernst equation, which for an electrochemical half-cell is For a complete electrochemical reaction (full cell), the equation can be written as Ecell is the cell potential (electromotive force) at the temperature of interest, R is the universal ideal gas constant: R = 8.31446261815324 J K−1 mol−1, z is the number of electrons transferred in the cell reaction or half-reaction, F is Faraday''s constant, the magnitude of charge (in coulombs) per mole of electrons: F = 96485.3321233100184 C mol−1, a is the chemical activity for the relevant species, where aRed is the activity of the reduced form and aOx is the activity of the oxidized form.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'electrochemistry', 'Nernst equation: Thermal voltage', 'is approximately 25.693 mV. The Nernst equation is frequently expressed in terms of base-10 logarithms (i.e., common logarithms) rather than natural logarithms, in which case it is written:', 'Wikipedia: Nernst equation', 'https://en.wikipedia.org/w/index.php?title=Nernst_equation&oldid=1376884524', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
